-- 2026-09-10 M05接收数据库设计稿；未执行数据库。MySQL 8.0.16+ 的8.x目标。
-- 先完成发送20列包；停所有管理/采集/签批写入，核准备份与SHOW CREATE TABLE差异；禁止--force。
-- DDL隐式提交，失败即停并逐对象核对，不自动重跑或覆盖备份。
SET NAMES utf8mb4;
-- 迁移后、功能启用前执行；零差异/默认状态不代表工程验收通过。
SELECT table_name,COUNT(*) AS column_count FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name IN ('det_sample','det_result','det_result_item','det_device_event') GROUP BY table_name;
SELECT table_name,constraint_name,check_clause FROM information_schema.check_constraints JOIN information_schema.table_constraints USING(constraint_schema,constraint_name) WHERE constraint_schema=DATABASE() AND constraint_name LIKE 'ck_m05_rx_%';
SELECT COUNT(*) AS det_sample_changed_or_new FROM `det_sample` a LEFT JOIN `bak_m05_rx_20260910_det_sample` b ON a.`sample_id`=b.`sample_id` WHERE b.`sample_id` IS NULL OR NOT ((CAST(a.`sample_id` AS BINARY) <=> CAST(b.`sample_id` AS BINARY)) AND (CAST(a.`sample_no` AS BINARY) <=> CAST(b.`sample_no` AS BINARY)) AND (CAST(a.`second_id` AS BINARY) <=> CAST(b.`second_id` AS BINARY)) AND (CAST(a.`project_id` AS BINARY) <=> CAST(b.`project_id` AS BINARY)) AND (CAST(a.`batch_id` AS BINARY) <=> CAST(b.`batch_id` AS BINARY)) AND (CAST(a.`culture_id` AS BINARY) <=> CAST(b.`culture_id` AS BINARY)) AND (CAST(a.`lab_id` AS BINARY) <=> CAST(b.`lab_id` AS BINARY)) AND (CAST(a.`detector_id` AS BINARY) <=> CAST(b.`detector_id` AS BINARY)) AND (CAST(a.`detect_class` AS BINARY) <=> CAST(b.`detect_class` AS BINARY)) AND (CAST(a.`detect_type` AS BINARY) <=> CAST(b.`detect_type` AS BINARY)) AND (CAST(a.`detect_mode` AS BINARY) <=> CAST(b.`detect_mode` AS BINARY)) AND (CAST(a.`queue_status` AS BINARY) <=> CAST(b.`queue_status` AS BINARY)) AND (CAST(a.`send_batch_no` AS BINARY) <=> CAST(b.`send_batch_no` AS BINARY)) AND (CAST(a.`column_no` AS BINARY) <=> CAST(b.`column_no` AS BINARY)) AND (CAST(a.`channel_no` AS BINARY) <=> CAST(b.`channel_no` AS BINARY)) AND (CAST(a.`sample_position` AS BINARY) <=> CAST(b.`sample_position` AS BINARY)) AND (CAST(a.`day_number` AS BINARY) <=> CAST(b.`day_number` AS BINARY)) AND (CAST(a.`detect_count` AS BINARY) <=> CAST(b.`detect_count` AS BINARY)) AND (CAST(a.`temperature` AS BINARY) <=> CAST(b.`temperature` AS BINARY)) AND (CAST(a.`cell_type` AS BINARY) <=> CAST(b.`cell_type` AS BINARY)) AND (CAST(a.`dilution_factor` AS BINARY) <=> CAST(b.`dilution_factor` AS BINARY)) AND (CAST(a.`testing_start_time` AS BINARY) <=> CAST(b.`testing_start_time` AS BINARY)) AND (CAST(a.`testing_end_time` AS BINARY) <=> CAST(b.`testing_end_time` AS BINARY)) AND (CAST(a.`del_flag` AS BINARY) <=> CAST(b.`del_flag` AS BINARY)) AND (CAST(a.`clear_flag` AS BINARY) <=> CAST(b.`clear_flag` AS BINARY)) AND (CAST(a.`create_by` AS BINARY) <=> CAST(b.`create_by` AS BINARY)) AND (CAST(a.`create_time` AS BINARY) <=> CAST(b.`create_time` AS BINARY)) AND (CAST(a.`update_by` AS BINARY) <=> CAST(b.`update_by` AS BINARY)) AND (CAST(a.`update_time` AS BINARY) <=> CAST(b.`update_time` AS BINARY)) AND (CAST(a.`remark` AS BINARY) <=> CAST(b.`remark` AS BINARY)) AND (CAST(a.`object_version` AS BINARY) <=> CAST(b.`object_version` AS BINARY)) AND (CAST(a.`created_user_id` AS BINARY) <=> CAST(b.`created_user_id` AS BINARY)) AND (CAST(a.`sent_user_id` AS BINARY) <=> CAST(b.`sent_user_id` AS BINARY)) AND (CAST(a.`occupancy_generation` AS BINARY) <=> CAST(b.`occupancy_generation` AS BINARY)) AND (CAST(a.`occupancy_state` AS BINARY) <=> CAST(b.`occupancy_state` AS BINARY)) AND (CAST(a.`draft_source` AS BINARY) <=> CAST(b.`draft_source` AS BINARY)) AND (CAST(a.`current_dispatch_id` AS BINARY) <=> CAST(b.`current_dispatch_id` AS BINARY)) AND (CAST(a.`send_requested_at` AS BINARY) <=> CAST(b.`send_requested_at` AS BINARY)));
SELECT COUNT(*) AS det_sample_missing FROM `bak_m05_rx_20260910_det_sample` b LEFT JOIN `det_sample` a ON a.`sample_id`=b.`sample_id` WHERE a.`sample_id` IS NULL;
SELECT COUNT(*) AS det_sample_nondefault FROM `det_sample` WHERE NOT (`actual_started_at` <=> NULL) OR NOT (`completion_observed_at` <=> NULL) OR NOT (`time_evidence` <=> NULL);
SELECT COUNT(*) AS det_result_changed_or_new FROM `det_result` a LEFT JOIN `bak_m05_rx_20260910_det_result` b ON a.`result_id`=b.`result_id` WHERE b.`result_id` IS NULL OR NOT ((CAST(a.`result_id` AS BINARY) <=> CAST(b.`result_id` AS BINARY)) AND (CAST(a.`sample_id` AS BINARY) <=> CAST(b.`sample_id` AS BINARY)) AND (CAST(a.`detector_id` AS BINARY) <=> CAST(b.`detector_id` AS BINARY)) AND (CAST(a.`detect_class` AS BINARY) <=> CAST(b.`detect_class` AS BINARY)) AND (CAST(a.`detect_type` AS BINARY) <=> CAST(b.`detect_type` AS BINARY)) AND (CAST(a.`result_status` AS BINARY) <=> CAST(b.`result_status` AS BINARY)) AND (CAST(a.`testing_end_time` AS BINARY) <=> CAST(b.`testing_end_time` AS BINARY)) AND (CAST(a.`testing_start_time` AS BINARY) <=> CAST(b.`testing_start_time` AS BINARY)) AND (CAST(a.`raw_data` AS BINARY) <=> CAST(b.`raw_data` AS BINARY)) AND (CAST(a.`review_by` AS BINARY) <=> CAST(b.`review_by` AS BINARY)) AND (CAST(a.`review_time` AS BINARY) <=> CAST(b.`review_time` AS BINARY)) AND (CAST(a.`sign_by` AS BINARY) <=> CAST(b.`sign_by` AS BINARY)) AND (CAST(a.`sign_time` AS BINARY) <=> CAST(b.`sign_time` AS BINARY)) AND (CAST(a.`void_reason` AS BINARY) <=> CAST(b.`void_reason` AS BINARY)) AND (CAST(a.`void_from_status` AS BINARY) <=> CAST(b.`void_from_status` AS BINARY)) AND (CAST(a.`exception_reason` AS BINARY) <=> CAST(b.`exception_reason` AS BINARY)) AND (CAST(a.`is_alarm` AS BINARY) <=> CAST(b.`is_alarm` AS BINARY)) AND (CAST(a.`del_flag` AS BINARY) <=> CAST(b.`del_flag` AS BINARY)) AND (CAST(a.`create_by` AS BINARY) <=> CAST(b.`create_by` AS BINARY)) AND (CAST(a.`create_time` AS BINARY) <=> CAST(b.`create_time` AS BINARY)) AND (CAST(a.`update_by` AS BINARY) <=> CAST(b.`update_by` AS BINARY)) AND (CAST(a.`update_time` AS BINARY) <=> CAST(b.`update_time` AS BINARY)) AND (CAST(a.`remark` AS BINARY) <=> CAST(b.`remark` AS BINARY)));
SELECT COUNT(*) AS det_result_missing FROM `bak_m05_rx_20260910_det_result` b LEFT JOIN `det_result` a ON a.`result_id`=b.`result_id` WHERE a.`result_id` IS NULL;
SELECT COUNT(*) AS det_result_nondefault FROM `det_result` WHERE NOT (`object_version` <=> 1) OR NOT (`result_completeness` <=> 'UNVERIFIED') OR NOT (`device_completion` <=> 'UNKNOWN') OR NOT (`collection_state` <=> 'UNVERIFIED') OR NOT (`actual_started_at` <=> NULL) OR NOT (`completion_observed_at` <=> NULL) OR NOT (`time_evidence` <=> NULL) OR NOT (`collection_basis` <=> NULL) OR NOT (`source_progress` <=> NULL) OR NOT (`last_event_id` <=> NULL) OR NOT (`next_collect_at` <=> NULL);
SELECT COUNT(*) AS det_result_item_changed_or_new FROM `det_result_item` a LEFT JOIN `bak_m05_rx_20260910_det_result_item` b ON a.`result_item_id`=b.`result_item_id` WHERE b.`result_item_id` IS NULL OR NOT ((CAST(a.`result_item_id` AS BINARY) <=> CAST(b.`result_item_id` AS BINARY)) AND (CAST(a.`result_id` AS BINARY) <=> CAST(b.`result_id` AS BINARY)) AND (CAST(a.`item_id` AS BINARY) <=> CAST(b.`item_id` AS BINARY)) AND (CAST(a.`item_code` AS BINARY) <=> CAST(b.`item_code` AS BINARY)) AND (CAST(a.`item_cn_name` AS BINARY) <=> CAST(b.`item_cn_name` AS BINARY)) AND (CAST(a.`item_en_name` AS BINARY) <=> CAST(b.`item_en_name` AS BINARY)) AND (CAST(a.`item_value` AS BINARY) <=> CAST(b.`item_value` AS BINARY)) AND (CAST(a.`numeric_value` AS BINARY) <=> CAST(b.`numeric_value` AS BINARY)) AND (CAST(a.`original_value` AS BINARY) <=> CAST(b.`original_value` AS BINARY)) AND (CAST(a.`unit` AS BINARY) <=> CAST(b.`unit` AS BINARY)) AND (CAST(a.`lower_limit` AS BINARY) <=> CAST(b.`lower_limit` AS BINARY)) AND (CAST(a.`upper_limit` AS BINARY) <=> CAST(b.`upper_limit` AS BINARY)) AND (CAST(a.`is_alarm` AS BINARY) <=> CAST(b.`is_alarm` AS BINARY)) AND (CAST(a.`is_voided` AS BINARY) <=> CAST(b.`is_voided` AS BINARY)) AND (CAST(a.`void_reason` AS BINARY) <=> CAST(b.`void_reason` AS BINARY)) AND (CAST(a.`create_time` AS BINARY) <=> CAST(b.`create_time` AS BINARY)) AND (CAST(a.`update_time` AS BINARY) <=> CAST(b.`update_time` AS BINARY)));
SELECT COUNT(*) AS det_result_item_missing FROM `bak_m05_rx_20260910_det_result_item` b LEFT JOIN `det_result_item` a ON a.`result_item_id`=b.`result_item_id` WHERE a.`result_item_id` IS NULL;
SELECT COUNT(*) AS det_result_item_nondefault FROM `det_result_item` WHERE NOT (`item_outcome` <=> 'UNKNOWN') OR NOT (`source_evidence` <=> NULL) OR NOT (`last_event_id` <=> NULL);
SELECT COUNT(*) AS received_events FROM det_device_event;

-- 复核新增7索引及原有键；逐项与10目标比较，不按总数替代定义审查。
SELECT table_name,index_name,non_unique,seq_in_index,column_name FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name IN ('det_sample','det_result','det_result_item','det_device_event') ORDER BY table_name,index_name,seq_in_index;
